use std::fs

struct Tree {
    keys: Vec<int>,
    left: Vec<int>,
    right: Vec<int>,
    root: int,
}

impl Tree {
    fn contains(self, x: int) -> bool {
        let mut cur = self.root
        while cur != -1 {
            let k = self.keys[cur as usize]
            if x == k {
                return true
            }
            if x < k {
                cur = self.left[cur as usize]
            } else {
                cur = self.right[cur as usize]
            }
        }
        false
    }

    fn insert(self, x: int) -> bool {
        let id = self.keys.len() as int
        if self.root == -1 {
            self.keys.push(x)
            self.left.push(-1)
            self.right.push(-1)
            self.root = id
            return true
        }
        let mut cur = self.root
        loop {
            let k = self.keys[cur as usize]
            if x == k {
                return false
            }
            if x < k {
                let l = self.left[cur as usize]
                if l == -1 {
                    self.keys.push(x)
                    self.left.push(-1)
                    self.right.push(-1)
                    self.left[cur as usize] = id
                    return true
                }
                cur = l
            } else {
                let r = self.right[cur as usize]
                if r == -1 {
                    self.keys.push(x)
                    self.left.push(-1)
                    self.right.push(-1)
                    self.right[cur as usize] = id
                    return true
                }
                cur = r
            }
        }
        true
    }

    fn replace_child(self, parent: int, old: int, new: int) {
        if parent == -1 {
            self.root = new
        } else if self.left[parent as usize] == old {
            self.left[parent as usize] = new
        } else {
            self.right[parent as usize] = new
        }
    }

    fn delete(self, x: int) -> bool {
        let mut parent = -1
        let mut cur = self.root
        while cur != -1 {
            let k = self.keys[cur as usize]
            if x == k {
                break
            }
            parent = cur
            if x < k {
                cur = self.left[cur as usize]
            } else {
                cur = self.right[cur as usize]
            }
        }
        if cur == -1 {
            return false
        }
        let l = self.left[cur as usize]
        let r = self.right[cur as usize]
        if l == -1 {
            self.replace_child(parent, cur, r)
        } else if r == -1 {
            self.replace_child(parent, cur, l)
        } else {
            let mut sp = cur
            let mut s = r
            while self.left[s as usize] != -1 {
                sp = s
                s = self.left[s as usize]
            }
            self.keys[cur as usize] = self.keys[s as usize]
            let sr = self.right[s as usize]
            self.replace_child(sp, s, sr)
        }
        true
    }

    fn height_of(self, n: int) -> int {
        if n == -1 {
            return 0
        }
        let a = self.height_of(self.left[n as usize])
        let b = self.height_of(self.right[n as usize])
        if a > b { a + 1 } else { b + 1 }
    }

    fn inorder(self) -> string {
        let mut out = ""
        let mut stack: Vec<int> = []
        let mut cur = self.root
        let mut first = true
        while cur != -1 || stack.len() > 0 {
            while cur != -1 {
                stack.push(cur)
                cur = self.left[cur as usize]
            }
            let n = stack.pop().unwrap_or(-1)
            if !first {
                out = out + " "
            }
            first = false
            out = out + "${self.keys[n as usize]}"
            cur = self.right[n as usize]
        }
        if first { "<empty>" } else { out }
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree { keys: [], left: [], right: [], root: -1 }
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0].as_str()
        let arg: int = if parts.len() > 1 { parts[1].parse::<int>().unwrap_or(0) } else { 0 }
        if cmd == "insert" {
            if t.insert(arg) { println("ok") } else { println("dup") }
        } else if cmd == "contains" {
            if t.contains(arg) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            if t.delete(arg) { println("ok") } else { println("missing") }
        } else if cmd == "inorder" {
            println(t.inorder())
        } else if cmd == "height" {
            println("${t.height_of(t.root)}")
        } else if cmd == "min" {
            if t.root == -1 {
                println("empty")
            } else {
                let mut c = t.root
                while t.left[c as usize] != -1 {
                    c = t.left[c as usize]
                }
                println("${t.keys[c as usize]}")
            }
        } else if cmd == "max" {
            if t.root == -1 {
                println("empty")
            } else {
                let mut c = t.root
                while t.right[c as usize] != -1 {
                    c = t.right[c as usize]
                }
                println("${t.keys[c as usize]}")
            }
        }
    }
}

